namespace {
constexpr int D=384,I=1536,H=12,HD=32,LAYERS=12,PARAMS=197;
constexpr int FP32=0,FP16=1,BF16=2;
enum Stage {STAGE_EMBEDDINGS=1,STAGE_EMBEDDING_LN=2,STAGE_Q=3,STAGE_K=4,STAGE_V=5,STAGE_SCORES=6,STAGE_SOFTMAX=7,STAGE_CONTEXT=8,STAGE_ATTENTION_OUTPUT=9,STAGE_ATTENTION_LN=10,STAGE_FFN_INPUT=11,STAGE_GELU=12,STAGE_FFN_OUTPUT=13,STAGE_FFN_LN=14,STAGE_CLS=15,STAGE_L2=16};
struct InvalidValue {int category=0,stage=0,layer=-1;unsigned long long index=0;float value=0;};

struct Model {
    void* p[PARAMS]{};size_t n[PARAMS]{};cublasHandle_t blas{};cudaStream_t stream{};bool ready=false;int precision=FP32;
    int64_t *di=nullptr,*dt=nullptr;uint8_t* dm=nullptr;
    void *a=nullptr,*b=nullptr,*q=nullptr,*k=nullptr,*v=nullptr,*merged=nullptr,*tmp=nullptr,*inter=nullptr;float* result=nullptr;
    size_t row_capacity=0,batch_capacity=0;cudaGraph_t graph{};cudaGraphExec_t graph_exec{};int graph_batch=0,graph_seq=0,math_mode=0;bool graph_enabled=true,graph_warmed=false;
    uint64_t forward_mallocs=0,forward_frees=0,kernel_launches=0,parameter_uploads=0,workspace_reallocations=0,h2d_bytes=0,d2h_bytes=0,synchronizations=0;
    uint64_t graph_launches=0,internal_submissions=0,graph_captures=0,graph_invalidations=0,parameter_bytes=0,workspace_bytes=0,conversion_ns=0,upload_ns=0,validation_ns=0,transpose_ns=0;
    int last_batch=0,last_seq=0;bool last_graph_captured=false,last_graph_reused=false;
};

bool ok(cudaError_t value){return value==cudaSuccess;}bool okb(cublasStatus_t value){return value==CUBLAS_STATUS_SUCCESS;}
size_t element_size(const Model* m){return m->precision==FP32?sizeof(float):sizeof(uint16_t);}

template<class T> __device__ float read_value(const T* p,size_t i){return (float)p[i];}
template<> __device__ float read_value<__half>(const __half* p,size_t i){return __half2float(p[i]);}
template<> __device__ float read_value<__nv_bfloat16>(const __nv_bfloat16* p,size_t i){return __bfloat162float(p[i]);}
template<class T> __device__ void write_value(T* p,size_t i,float v){p[i]=(T)v;}
template<> __device__ void write_value<__half>(__half* p,size_t i,float v){p[i]=__float2half_rn(v);}
template<> __device__ void write_value<__nv_bfloat16>(__nv_bfloat16* p,size_t i,float v){p[i]=__float2bfloat16_rn(v);}
__device__ void record_invalid(InvalidValue* invalid,int stage,int layer,size_t index,float value){if(!invalid||isfinite(value))return;int category=isnan(value)?1:(value>0?2:3);if(atomicCAS(&invalid->category,0,category)==0){invalid->stage=stage;invalid->layer=layer;invalid->index=index;invalid->value=value;}}
template<class T> __global__ void scan_finite(const T* values,size_t count,InvalidValue* invalid,int stage,int layer){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<count)record_invalid(invalid,stage,layer,i,read_value(values,i));}
template<class T> __global__ void copy_float32(const T* values,float* output,size_t count){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<count)output[i]=read_value(values,i);}

void invalidate_graph(Model* m){bool existed=m->graph_exec||m->graph;if(m->graph_exec)cudaGraphExecDestroy(m->graph_exec);if(m->graph)cudaGraphDestroy(m->graph);if(existed)m->graph_invalidations++;m->graph_exec=nullptr;m->graph=nullptr;m->graph_batch=0;m->graph_seq=0;m->graph_warmed=false;}
void release_workspace(Model* m){invalidate_graph(m);void* allocations[]={m->di,m->dt,m->dm,m->a,m->b,m->q,m->k,m->v,m->merged,m->tmp,m->inter,m->result};for(void* p:allocations)if(p)m->forward_frees++;cudaFree(m->di);cudaFree(m->dt);cudaFree(m->dm);cudaFree(m->a);cudaFree(m->b);cudaFree(m->q);cudaFree(m->k);cudaFree(m->v);cudaFree(m->merged);cudaFree(m->tmp);cudaFree(m->inter);cudaFree(m->result);m->di=m->dt=nullptr;m->dm=nullptr;m->a=m->b=m->q=m->k=m->v=m->merged=m->tmp=m->inter=m->result=nullptr;m->row_capacity=m->batch_capacity=0;m->workspace_bytes=0;}
bool ensure_workspace(Model* m,int batch,int seq){
    if(batch<1||seq<1)return false;size_t rows=(size_t)batch*seq;if(rows>std::numeric_limits<size_t>::max()/D||rows>std::numeric_limits<size_t>::max()/I)return false;size_t attention_rows=(size_t)batch*H*seq;if(attention_rows>std::numeric_limits<size_t>::max()/(size_t)seq)return false;(void)(attention_rows*seq);
    if(rows<=m->row_capacity&&(size_t)batch<=m->batch_capacity)return true;size_t new_rows=rows>m->row_capacity?rows:m->row_capacity,new_batch=(size_t)batch>m->batch_capacity?(size_t)batch:m->batch_capacity,bytes=element_size(m);release_workspace(m);m->workspace_reallocations++;
    #define ALLOC(ptr,size) if(!ok(cudaMalloc(&(m->ptr),(size)))){release_workspace(m);return false;}else{m->forward_mallocs++;m->workspace_bytes+=(size);}
    ALLOC(di,new_rows*sizeof(int64_t));ALLOC(dt,new_rows*sizeof(int64_t));ALLOC(dm,new_rows);ALLOC(a,new_rows*D*bytes);ALLOC(b,new_rows*D*bytes);ALLOC(q,new_rows*D*bytes);ALLOC(k,new_rows*D*bytes);ALLOC(v,new_rows*D*bytes);ALLOC(merged,new_rows*D*bytes);ALLOC(tmp,new_rows*D*bytes);ALLOC(inter,new_rows*I*bytes);ALLOC(result,new_batch*D*sizeof(float));
    #undef ALLOC
    m->row_capacity=new_rows;m->batch_capacity=new_batch;return true;
}

template<class T> __global__ void embeddings(const int64_t* ids,const int64_t* types,T* out,const T* word,const T* pos,const T* type,int rows,int seq){int index=blockIdx.x*blockDim.x+threadIdx.x,total=rows*seq*D;if(index<total){int token=index/D,d=index%D;float sum=read_value(word,(size_t)ids[token]*D+d)+read_value(pos,(size_t)(token%seq)*D+d)+read_value(type,(size_t)types[token]*D+d);write_value(out,index,sum);}}
template<class T> __global__ void layer_norm(const T* a,const T* residual,T* out,const T* gamma,const T* beta,int rows){
    __shared__ double means[128],m2s[128];__shared__ int counts[128];int r=blockIdx.x,tid=threadIdx.x;if(r>=rows)return;double mean=0,m2=0;int count=0;
    for(int d=tid;d<D;d+=blockDim.x){double x=read_value(a,(size_t)r*D+d)+(residual?(double)read_value(residual,(size_t)r*D+d):0.0);count++;double delta=x-mean;mean+=delta/count;m2+=delta*(x-mean);}means[tid]=mean;m2s[tid]=m2;counts[tid]=count;__syncthreads();
    for(int offset=64;offset>0;offset/=2){if(tid<offset){int right=tid+offset,n1=counts[tid],n2=counts[right];if(n2){double delta=means[right]-means[tid],n=n1+n2;means[tid]+=delta*n2/n;m2s[tid]+=m2s[right]+delta*delta*n1*n2/n;counts[tid]=n;}}__syncthreads();}
    double inv=rsqrt(m2s[0]/D+1e-12);for(int d=tid;d<D;d+=blockDim.x){double x=read_value(a,(size_t)r*D+d)+(residual?(double)read_value(residual,(size_t)r*D+d):0.0);float result=read_value(gamma,d)*(float)((x-means[0])*inv)+read_value(beta,d);write_value(out,(size_t)r*D+d,result);}
}
template<class T> __global__ void bias(T* out,const T* values,int rows,int width){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<rows*width)write_value(out,i,read_value(out,i)+read_value(values,i%width));}
template<class T> __global__ void gelu(T* values,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n){float x=read_value(values,i);write_value(values,i,0.5f*x*(1.0f+erff(x*0.7071067811865475f)));}}
template<class T> __global__ void fused_attention(const T* q,const T* k,const T* v,const uint8_t* mask,T* merged,int batch,int seq,InvalidValue* invalid=nullptr,int layer=-1){
    __shared__ float probabilities[512],reduction[128],maximum;int row=blockIdx.x,tid=threadIdx.x,lane=tid&31,warp=tid>>5;if(row>=batch*H*seq)return;int query=row%seq,head=(row/seq)%H,b=row/(H*seq);
    for(int key=warp;key<seq;key+=4){float score=read_value(q,((size_t)b*seq+query)*D+head*HD+lane)*read_value(k,((size_t)b*seq+key)*D+head*HD+lane);for(int offset=16;offset>0;offset/=2)score+=__shfl_down_sync(0xffffffff,score,offset);if(lane==0){score*=0.1767766952966369f;if(mask[b*seq+key])record_invalid(invalid,STAGE_SCORES,layer,(size_t)row*seq+key,score);probabilities[key]=mask[b*seq+key]?score:-INFINITY;}}
    __syncthreads();float local_max=-INFINITY;for(int key=tid;key<seq;key+=blockDim.x)local_max=fmaxf(local_max,probabilities[key]);reduction[tid]=local_max;__syncthreads();for(int offset=64;offset>0;offset/=2){if(tid<offset)reduction[tid]=fmaxf(reduction[tid],reduction[tid+offset]);__syncthreads();}
    if(tid==0)maximum=reduction[0];__syncthreads();float local_sum=0;for(int key=tid;key<seq;key+=blockDim.x){float value=mask[b*seq+key]?expf(probabilities[key]-maximum):0;probabilities[key]=value;local_sum+=value;}reduction[tid]=local_sum;__syncthreads();for(int offset=64;offset>0;offset/=2){if(tid<offset)reduction[tid]+=reduction[tid+offset];__syncthreads();}if(tid==0&&(!isfinite(reduction[0])||reduction[0]<=0))record_invalid(invalid,STAGE_SOFTMAX,layer,row,reduction[0]);for(int key=tid;key<seq;key+=blockDim.x){probabilities[key]/=reduction[0];record_invalid(invalid,STAGE_SOFTMAX,layer,(size_t)row*seq+key,probabilities[key]);}__syncthreads();
    if(tid<HD){float sum=0;int d=head*HD+tid;for(int key=0;key<seq;key++)sum+=probabilities[key]*read_value(v,((size_t)b*seq+key)*D+d);record_invalid(invalid,STAGE_CONTEXT,layer,((size_t)b*seq+query)*D+d,sum);write_value(merged,((size_t)b*seq+query)*D+d,sum);}
}
template<class T> __global__ void cls_l2(const T* hidden,float* out,int batch,int seq){__shared__ double sums[128];int b=blockIdx.x,tid=threadIdx.x;if(b>=batch)return;double sum=0;for(int d=tid;d<D;d+=blockDim.x){double value=read_value(hidden,(size_t)b*seq*D+d);sum+=value*value;}sums[tid]=sum;__syncthreads();for(int offset=64;offset>0;offset/=2){if(tid<offset)sums[tid]+=sums[tid+offset];__syncthreads();}double inv=rsqrt(sums[0]);for(int d=tid;d<D;d+=blockDim.x)out[b*D+d]=(float)(read_value(hidden,(size_t)b*seq*D+d)*inv);}

template<class T> cudaDataType_t cuda_type();template<> cudaDataType_t cuda_type<__half>(){return CUDA_R_16F;}template<> cudaDataType_t cuda_type<__nv_bfloat16>(){return CUDA_R_16BF;}
template<class T> bool linear_mixed(Model* m,const T* a,const T* w,const T* b,T* c,int rows,int k,int n){const float alpha=1,beta=0;if(!okb(cublasGemmEx(m->blas,CUBLAS_OP_N,CUBLAS_OP_N,n,rows,k,&alpha,w,cuda_type<T>(),n,a,cuda_type<T>(),k,&beta,c,cuda_type<T>(),n,CUBLAS_COMPUTE_32F,CUBLAS_GEMM_DEFAULT_TENSOR_OP)))return false;bias<<<(rows*n+255)/256,256,0,m->stream>>>(c,b,rows,n);return ok(cudaGetLastError());}
bool linear_fp32(Model* m,const float* a,const float* w,const float* b,float* c,int rows,int k,int n){const float alpha=1,beta=0;if(!okb(cublasSgemm(m->blas,CUBLAS_OP_N,CUBLAS_OP_N,n,rows,k,&alpha,w,n,a,k,&beta,c,n)))return false;bias<<<(rows*n+255)/256,256,0,m->stream>>>(c,b,rows,n);return ok(cudaGetLastError());}
template<class T> bool linear_any(Model* m,const T* a,const T* w,const T* b,T* c,int rows,int k,int n){return linear_mixed(m,a,w,b,c,rows,k,n);}template<> bool linear_any<float>(Model* m,const float* a,const float* w,const float* b,float* c,int rows,int k,int n){return linear_fp32(m,a,w,b,c,rows,k,n);}
template<class T> bool launch_typed(Model* m,int batch,int seq,int rows,size_t dn){
    auto p=[&](int i){return (T*)m->p[i];};T* a=(T*)m->a;T* b=(T*)m->b;T* q=(T*)m->q;T* k=(T*)m->k;T* v=(T*)m->v;T* merged=(T*)m->merged;T* tmp=(T*)m->tmp;T* inter=(T*)m->inter;
    embeddings<<<(dn+255)/256,256,0,m->stream>>>(m->di,m->dt,tmp,p(0),p(1),p(2),batch,seq);layer_norm<<<rows,128,0,m->stream>>>(tmp,(T*)nullptr,a,p(3),p(4),rows);
    for(int layer=0;layer<LAYERS;layer++){int x=5+layer*16;if(!linear_mixed(m,a,p(x),p(x+1),q,rows,D,D)||!linear_mixed(m,a,p(x+2),p(x+3),k,rows,D,D)||!linear_mixed(m,a,p(x+4),p(x+5),v,rows,D,D))return false;fused_attention<<<batch*H*seq,128,0,m->stream>>>(q,k,v,m->dm,merged,batch,seq);if(!linear_mixed(m,merged,p(x+6),p(x+7),tmp,rows,D,D))return false;layer_norm<<<rows,128,0,m->stream>>>(tmp,a,b,p(x+8),p(x+9),rows);if(!linear_mixed(m,b,p(x+10),p(x+11),inter,rows,D,I))return false;gelu<<<((size_t)rows*I+255)/256,256,0,m->stream>>>(inter,rows*I);if(!linear_mixed(m,inter,p(x+12),p(x+13),tmp,rows,I,D))return false;layer_norm<<<rows,128,0,m->stream>>>(tmp,b,a,p(x+14),p(x+15),rows);}
    cls_l2<<<batch,128,0,m->stream>>>(a,m->result,batch,seq);return ok(cudaGetLastError());
}
bool launch_fp32(Model* m,int batch,int seq,int rows,size_t dn){
    auto p=[&](int i){return (float*)m->p[i];};float* a=(float*)m->a;float* b=(float*)m->b;float* q=(float*)m->q;float* k=(float*)m->k;float* v=(float*)m->v;float* merged=(float*)m->merged;float* tmp=(float*)m->tmp;float* inter=(float*)m->inter;
    embeddings<<<(dn+255)/256,256,0,m->stream>>>(m->di,m->dt,tmp,p(0),p(1),p(2),batch,seq);layer_norm<<<rows,128,0,m->stream>>>(tmp,(float*)nullptr,a,p(3),p(4),rows);
    for(int layer=0;layer<LAYERS;layer++){int x=5+layer*16;if(!linear_fp32(m,a,p(x),p(x+1),q,rows,D,D)||!linear_fp32(m,a,p(x+2),p(x+3),k,rows,D,D)||!linear_fp32(m,a,p(x+4),p(x+5),v,rows,D,D))return false;fused_attention<<<batch*H*seq,128,0,m->stream>>>(q,k,v,m->dm,merged,batch,seq);if(!linear_fp32(m,merged,p(x+6),p(x+7),tmp,rows,D,D))return false;layer_norm<<<rows,128,0,m->stream>>>(tmp,a,b,p(x+8),p(x+9),rows);if(!linear_fp32(m,b,p(x+10),p(x+11),inter,rows,D,I))return false;gelu<<<((size_t)rows*I+255)/256,256,0,m->stream>>>(inter,rows*I);if(!linear_fp32(m,inter,p(x+12),p(x+13),tmp,rows,I,D))return false;layer_norm<<<rows,128,0,m->stream>>>(tmp,b,a,p(x+14),p(x+15),rows);}cls_l2<<<batch,128,0,m->stream>>>(a,m->result,batch,seq);return ok(cudaGetLastError());
}
bool launch_pipeline(Model* m,int batch,int seq,int rows,size_t dn){if(m->precision==FP16)return launch_typed<__half>(m,batch,seq,rows,dn);if(m->precision==BF16)return launch_typed<__nv_bfloat16>(m,batch,seq,rows,dn);return launch_fp32(m,batch,seq,rows,dn);}
template<class T> bool launch_diagnostic(Model* m,int batch,int seq,int rows,size_t dn,InvalidValue* invalid,float* snapshots){
    auto p=[&](int i){return (T*)m->p[i];};T* a=(T*)m->a;T* b=(T*)m->b;T* q=(T*)m->q;T* k=(T*)m->k;T* v=(T*)m->v;T* merged=(T*)m->merged;T* tmp=(T*)m->tmp;T* inter=(T*)m->inter;int blocks=(int)((dn+255)/256);auto scan=[&](T* values,size_t count,int stage,int layer){scan_finite<<<(count+255)/256,256,0,m->stream>>>(values,count,invalid,stage,layer);};auto snapshot=[&](int state){if(snapshots)copy_float32<<<blocks,256,0,m->stream>>>(a,snapshots+(size_t)state*dn,dn);};
    embeddings<<<blocks,256,0,m->stream>>>(m->di,m->dt,tmp,p(0),p(1),p(2),batch,seq);scan(tmp,dn,STAGE_EMBEDDINGS,-1);layer_norm<<<rows,128,0,m->stream>>>(tmp,(T*)nullptr,a,p(3),p(4),rows);scan(a,dn,STAGE_EMBEDDING_LN,-1);snapshot(0);
    for(int layer=0;layer<LAYERS;layer++){int x=5+layer*16;if(!linear_any(m,a,p(x),p(x+1),q,rows,D,D)||!linear_any(m,a,p(x+2),p(x+3),k,rows,D,D)||!linear_any(m,a,p(x+4),p(x+5),v,rows,D,D))return false;scan(q,dn,STAGE_Q,layer);scan(k,dn,STAGE_K,layer);scan(v,dn,STAGE_V,layer);fused_attention<<<batch*H*seq,128,0,m->stream>>>(q,k,v,m->dm,merged,batch,seq,invalid,layer);scan(merged,dn,STAGE_CONTEXT,layer);if(!linear_any(m,merged,p(x+6),p(x+7),tmp,rows,D,D))return false;scan(tmp,dn,STAGE_ATTENTION_OUTPUT,layer);layer_norm<<<rows,128,0,m->stream>>>(tmp,a,b,p(x+8),p(x+9),rows);scan(b,dn,STAGE_ATTENTION_LN,layer);if(!linear_any(m,b,p(x+10),p(x+11),inter,rows,D,I))return false;scan(inter,(size_t)rows*I,STAGE_FFN_INPUT,layer);gelu<<<((size_t)rows*I+255)/256,256,0,m->stream>>>(inter,rows*I);scan(inter,(size_t)rows*I,STAGE_GELU,layer);if(!linear_any(m,inter,p(x+12),p(x+13),tmp,rows,I,D))return false;scan(tmp,dn,STAGE_FFN_OUTPUT,layer);layer_norm<<<rows,128,0,m->stream>>>(tmp,b,a,p(x+14),p(x+15),rows);scan(a,dn,STAGE_FFN_LN,layer);snapshot(layer+1);}
    scan(a,(size_t)batch*D,STAGE_CLS,-1);cls_l2<<<batch,128,0,m->stream>>>(a,m->result,batch,seq);scan_finite<<<((size_t)batch*D+255)/256,256,0,m->stream>>>(m->result,(size_t)batch*D,invalid,STAGE_L2,-1);return ok(cudaGetLastError());
}
int expected_count(int index){if(index==0)return 30522*D;if(index==1)return 512*D;if(index==2)return 2*D;if(index<5)return D;int slot=(index-5)%16;if(slot==0||slot==2||slot==4||slot==6)return D*D;if(slot==10)return D*I;if(slot==11)return I;if(slot==12)return I*D;return D;}

uint16_t float_to_bf16(float value){uint32_t bits;std::memcpy(&bits,&value,sizeof(bits));bits+=0x7fffu+((bits>>16u)&1u);return (uint16_t)(bits>>16u);}
float read_le_f32(const uint8_t* data,size_t index){uint32_t bits=(uint32_t)data[index*4]|(uint32_t)data[index*4+1]<<8u|(uint32_t)data[index*4+2]<<16u|(uint32_t)data[index*4+3]<<24u;float value;std::memcpy(&value,&bits,sizeof(value));return value;}
int upload_parameter(Model* m,int index,const uint8_t* data,size_t byte_count,int rows,int columns,bool transpose){
    if(!m||!data||index<0||index>=PARAMS||m->p[index]||rows<1||columns<1)return 1;size_t count=(size_t)expected_count(index);if((size_t)rows>std::numeric_limits<size_t>::max()/(size_t)columns||(size_t)rows*columns!=count||count>std::numeric_limits<size_t>::max()/4||byte_count!=count*4)return 1;
    auto validation_start=std::chrono::steady_clock::now();for(size_t i=0;i<count;i++)if(!std::isfinite(read_le_f32(data,i)))return 1;m->validation_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-validation_start).count();
    std::vector<float> reordered;const uint8_t* source=data;if(transpose){auto start=std::chrono::steady_clock::now();try{reordered.resize(count);}catch(...){return 2;}constexpr int TILE=32;for(int r0=0;r0<rows;r0+=TILE)for(int c0=0;c0<columns;c0+=TILE)for(int r=r0;r<rows&&r<r0+TILE;r++)for(int c=c0;c<columns&&c<c0+TILE;c++)reordered[(size_t)c*rows+r]=read_le_f32(data,(size_t)r*columns+c);source=(const uint8_t*)reordered.data();m->transpose_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();}
    size_t bytes=count*(m->precision==FP32?4u:2u);void* device=nullptr;if(!ok(cudaMalloc(&device,bytes)))return 2;bool copied=false;auto convert_start=std::chrono::steady_clock::now(),upload_start=convert_start;
    if(m->precision==FP32){upload_start=std::chrono::steady_clock::now();copied=ok(cudaMemcpy(device,source,bytes,cudaMemcpyHostToDevice));}
    else if(m->precision==FP16){std::vector<__half> converted;try{converted.resize(count);}catch(...){cudaFree(device);return 2;}for(size_t i=0;i<count;i++)converted[i]=__float2half_rn(transpose?reordered[i]:read_le_f32(data,i));upload_start=std::chrono::steady_clock::now();m->conversion_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(upload_start-convert_start).count();copied=ok(cudaMemcpy(device,converted.data(),bytes,cudaMemcpyHostToDevice));}
    else{std::vector<uint16_t> converted;try{converted.resize(count);}catch(...){cudaFree(device);return 2;}for(size_t i=0;i<count;i++)converted[i]=float_to_bf16(transpose?reordered[i]:read_le_f32(data,i));upload_start=std::chrono::steady_clock::now();m->conversion_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(upload_start-convert_start).count();copied=ok(cudaMemcpy(device,converted.data(),bytes,cudaMemcpyHostToDevice));}
    m->upload_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-upload_start).count();if(!copied){cudaFree(device);return 2;}m->p[index]=device;m->n[index]=count;m->parameter_uploads++;m->parameter_bytes+=bytes;return 0;
