void* create_model(int precision){if(precision<FP32||precision>BF16)return nullptr;Model* m=new(std::nothrow)Model;if(!m)return nullptr;m->precision=precision;if(!ok(cudaStreamCreateWithFlags(&m->stream,cudaStreamNonBlocking))||!okb(cublasCreate(&m->blas))||!okb(cublasSetStream(m->blas,m->stream))||!okb(cublasSetMathMode(m->blas,CUBLAS_PEDANTIC_MATH))){if(m->blas)cublasDestroy(m->blas);if(m->stream)cudaStreamDestroy(m->stream);delete m;return nullptr;}return m;}
}

extern "C" int cuda_bge_available_impl(){int count=0;return ok(cudaGetDeviceCount(&count))&&count>0;}
extern "C" void* cuda_bge_create_impl(){return create_model(FP32);}extern "C" void* cuda_bge_create_precision_impl(int precision){return create_model(precision);}
extern "C" int cuda_bge_set_parameter_impl(void* handle,int index,const float* data,size_t count){
    return count>std::numeric_limits<size_t>::max()/4?1:upload_parameter((Model*)handle,index,(const uint8_t*)data,count*4,(int)count,1,false);
}
extern "C" int cuda_bge_set_parameter_bytes_impl(void* handle,int index,const uint8_t* data,size_t byte_count,int rows,int columns,int transpose){if(transpose!=0&&transpose!=1)return 1;return upload_parameter((Model*)handle,index,data,byte_count,rows,columns,transpose!=0);}
