extern "C" int cuda_bge_set_math_mode_impl(void* handle,int mode){Model* m=(Model*)handle;if(!m||m->precision!=FP32||(mode!=0&&mode!=1))return 1;cublasMath_t selected=mode==0?CUBLAS_PEDANTIC_MATH:CUBLAS_TF32_TENSOR_OP_MATH;if(!okb(cublasSetMathMode(m->blas,selected)))return 1;if(m->math_mode!=mode)invalidate_graph(m);m->math_mode=mode;return 0;}
extern "C" int cuda_bge_set_graph_enabled_impl(void* handle,int enabled){Model* m=(Model*)handle;if(!m||(enabled!=0&&enabled!=1))return 1;if(m->graph_enabled!=(enabled!=0))invalidate_graph(m);m->graph_enabled=enabled!=0;return 0;}

int cuda_bge_forward_core(void* handle,const int64_t* ids,const uint8_t* mask,const int64_t* types,int batch,int seq,float* host_out,float* timings,int timing_capacity,int* timing_count,float* phase_timings){
    Model* m=(Model*)handle;if(!m||!m->ready||!ids||!mask||!types||!host_out||batch<1||seq<1||seq>512||timings&&m->precision!=FP32)return 1;if((size_t)batch>std::numeric_limits<size_t>::max()/(size_t)seq)return 1;size_t row_count=(size_t)batch*seq;if(row_count>(size_t)std::numeric_limits<int>::max()||row_count>std::numeric_limits<size_t>::max()/D)return 1;int rows=(int)row_count;size_t dn=row_count*D;for(int i=0;i<rows;i++)if(ids[i]<0||ids[i]>=30522||types[i]<0||types[i]>=2)return 1;for(int b=0;b<batch;b++){bool any=false;for(int s=0;s<seq;s++)any=any||mask[b*seq+s]!=0;if(!any)return 1;}
    m->forward_mallocs=0;m->forward_frees=0;m->kernel_launches=195;m->internal_submissions=195;m->h2d_bytes=row_count*17;m->d2h_bytes=(size_t)batch*D*4;m->synchronizations=1;m->last_batch=batch;m->last_seq=seq;m->last_graph_captured=false;m->last_graph_reused=false;if(!ensure_workspace(m,batch,seq))return 2;
    cudaEvent_t events[138]{};int marks=0;if(timings){if(timing_capacity<137||!timing_count)return 1;for(int i=0;i<138;i++)if(!ok(cudaEventCreate(&events[i])))return 2;cudaEventRecord(events[marks++],m->stream);}cudaEvent_t phases[4]{};if(phase_timings){for(int i=0;i<4;i++)if(!ok(cudaEventCreate(&phases[i])))return 2;cudaEventRecord(phases[0],m->stream);}
    #define MARK() if(timings)cudaEventRecord(events[marks++],m->stream)
    if(!ok(cudaMemcpyAsync(m->di,ids,rows*8,cudaMemcpyHostToDevice,m->stream))||!ok(cudaMemcpyAsync(m->dt,types,rows*8,cudaMemcpyHostToDevice,m->stream))||!ok(cudaMemcpyAsync(m->dm,mask,rows,cudaMemcpyHostToDevice,m->stream)))return 2;if(phase_timings)cudaEventRecord(phases[1],m->stream);
    if(!timings&&m->graph_enabled){if(m->graph_exec&&m->graph_batch==batch&&m->graph_seq==seq){if(!ok(cudaGraphLaunch(m->graph_exec,m->stream)))return 2;m->graph_launches++;m->kernel_launches=1;m->last_graph_reused=true;}else if(m->graph_warmed&&m->graph_batch==batch&&m->graph_seq==seq){if(!ok(cudaStreamBeginCapture(m->stream,cudaStreamCaptureModeGlobal))||!launch_pipeline(m,batch,seq,rows,dn))return 2;cudaGraph_t graph{};if(!ok(cudaStreamEndCapture(m->stream,&graph)))return 2;cudaGraphExec_t exec{};if(!ok(cudaGraphInstantiate(&exec,graph,nullptr,nullptr,0))){cudaGraphDestroy(graph);return 2;}invalidate_graph(m);m->graph=graph;m->graph_exec=exec;m->graph_batch=batch;m->graph_seq=seq;m->graph_warmed=true;m->graph_captures++;if(!ok(cudaGraphLaunch(exec,m->stream)))return 2;m->graph_launches++;m->kernel_launches=1;m->last_graph_captured=true;}else{invalidate_graph(m);m->graph_batch=batch;m->graph_seq=seq;m->graph_warmed=true;if(!launch_pipeline(m,batch,seq,rows,dn))return 2;}}
    else if(!timings){if(!launch_pipeline(m,batch,seq,rows,dn))return 2;}
    else{float* a=(float*)m->a;float* b=(float*)m->b;float* q=(float*)m->q;float* k=(float*)m->k;float* v=(float*)m->v;float* merged=(float*)m->merged;float* tmp=(float*)m->tmp;float* inter=(float*)m->inter;auto p=[&](int i){return(float*)m->p[i];};MARK();embeddings<<<(dn+255)/256,256,0,m->stream>>>(m->di,m->dt,tmp,p(0),p(1),p(2),batch,seq);MARK();layer_norm<<<rows,128,0,m->stream>>>(tmp,(float*)nullptr,a,p(3),p(4),rows);MARK();for(int layer=0;layer<LAYERS;layer++){int x=5+layer*16;if(!linear_fp32(m,a,p(x),p(x+1),q,rows,D,D))return 2;MARK();if(!linear_fp32(m,a,p(x+2),p(x+3),k,rows,D,D))return 2;MARK();if(!linear_fp32(m,a,p(x+4),p(x+5),v,rows,D,D))return 2;MARK();fused_attention<<<batch*H*seq,128,0,m->stream>>>(q,k,v,m->dm,merged,batch,seq);MARK();MARK();if(!linear_fp32(m,merged,p(x+6),p(x+7),tmp,rows,D,D))return 2;MARK();layer_norm<<<rows,128,0,m->stream>>>(tmp,a,b,p(x+8),p(x+9),rows);MARK();if(!linear_fp32(m,b,p(x+10),p(x+11),inter,rows,D,I))return 2;MARK();gelu<<<((size_t)rows*I+255)/256,256,0,m->stream>>>(inter,rows*I);MARK();if(!linear_fp32(m,inter,p(x+12),p(x+13),tmp,rows,I,D))return 2;MARK();layer_norm<<<rows,128,0,m->stream>>>(tmp,b,a,p(x+14),p(x+15),rows);MARK();}cls_l2<<<batch,128,0,m->stream>>>(a,m->result,batch,seq);MARK();}
    if(phase_timings)cudaEventRecord(phases[2],m->stream);if(!ok(cudaMemcpyAsync(host_out,m->result,(size_t)batch*D*4,cudaMemcpyDeviceToHost,m->stream)))return 2;MARK();if(phase_timings)cudaEventRecord(phases[3],m->stream);if(!ok(cudaStreamSynchronize(m->stream)))return 2;if(timings){*timing_count=marks-1;for(int i=0;i<marks-1;i++)cudaEventElapsedTime(&timings[i],events[i],events[i+1]);for(int i=0;i<marks;i++)cudaEventDestroy(events[i]);}if(phase_timings){for(int i=0;i<3;i++)cudaEventElapsedTime(&phase_timings[i],phases[i],phases[i+1]);for(auto event:phases)cudaEventDestroy(event);}return 0;
}
extern "C" int cuda_bge_forward_impl(void* h,const int64_t* i,const uint8_t* m,const int64_t* t,int b,int s,float* o){return cuda_bge_forward_core(h,i,m,t,b,s,o,nullptr,0,nullptr,nullptr);}extern "C" int cuda_bge_profile_impl(void* h,const int64_t* i,const uint8_t* m,const int64_t* t,int b,int s,float* o,float* times,int cap,int* count){return cuda_bge_forward_core(h,i,m,t,b,s,o,times,cap,count,nullptr);}extern "C" int cuda_bge_forward_detailed_impl(void* h,const int64_t* i,const uint8_t* m,const int64_t* t,int b,int s,float* o,float* phases){return phases?cuda_bge_forward_core(h,i,m,t,b,s,o,nullptr,0,nullptr,phases):1;}
extern "C" int cuda_bge_diagnose_impl(void* handle,const int64_t* ids,const uint8_t* mask,const int64_t* types,int batch,int seq,float* host_snapshots,size_t snapshot_count,uint64_t* metadata,float* invalid_value){
    Model* m=(Model*)handle;if(!m||!m->ready||!ids||!mask||!types||!metadata||!invalid_value||batch<1||seq<1||seq>512)return 1;if((size_t)batch>std::numeric_limits<size_t>::max()/(size_t)seq)return 1;size_t rows=(size_t)batch*seq;if(rows>std::numeric_limits<size_t>::max()/D)return 1;size_t dn=rows*D;if(dn>std::numeric_limits<size_t>::max()/13||((host_snapshots==nullptr)!=(snapshot_count==0))||(host_snapshots&&snapshot_count!=dn*13)||rows>(size_t)std::numeric_limits<int>::max())return 1;for(size_t i=0;i<rows;i++)if(ids[i]<0||ids[i]>=30522||types[i]<0||types[i]>=2)return 1;for(int b=0;b<batch;b++){bool any=false;for(int s=0;s<seq;s++)any=any||mask[b*seq+s]!=0;if(!any)return 1;}if(!ensure_workspace(m,batch,seq))return 2;
    InvalidValue* device_invalid=nullptr;float* device_snapshots=nullptr;if(!ok(cudaMalloc(&device_invalid,sizeof(InvalidValue)))||(host_snapshots&&!ok(cudaMalloc(&device_snapshots,snapshot_count*sizeof(float))))){cudaFree(device_invalid);cudaFree(device_snapshots);return 2;}InvalidValue zero{};bool success=ok(cudaMemcpyAsync(m->di,ids,rows*8,cudaMemcpyHostToDevice,m->stream))&&ok(cudaMemcpyAsync(m->dt,types,rows*8,cudaMemcpyHostToDevice,m->stream))&&ok(cudaMemcpyAsync(m->dm,mask,rows,cudaMemcpyHostToDevice,m->stream))&&ok(cudaMemcpyAsync(device_invalid,&zero,sizeof(zero),cudaMemcpyHostToDevice,m->stream));if(success){if(m->precision==FP16)success=launch_diagnostic<__half>(m,batch,seq,(int)rows,dn,device_invalid,device_snapshots);else if(m->precision==BF16)success=launch_diagnostic<__nv_bfloat16>(m,batch,seq,(int)rows,dn,device_invalid,device_snapshots);else success=launch_diagnostic<float>(m,batch,seq,(int)rows,dn,device_invalid,device_snapshots);}InvalidValue result{};if(success&&host_snapshots)success=ok(cudaMemcpyAsync(host_snapshots,device_snapshots,snapshot_count*4,cudaMemcpyDeviceToHost,m->stream));if(success)success=ok(cudaMemcpyAsync(&result,device_invalid,sizeof(result),cudaMemcpyDeviceToHost,m->stream))&&ok(cudaStreamSynchronize(m->stream));cudaFree(device_invalid);cudaFree(device_snapshots);if(!success)return 2;metadata[0]=(uint64_t)result.category;metadata[1]=(uint64_t)result.stage;metadata[2]=(uint64_t)(result.layer+1);metadata[3]=result.index;*invalid_value=result.value;return 0;
}
extern "C" void cuda_bge_destroy_impl(void* handle){Model* m=(Model*)handle;if(!m)return;release_workspace(m);for(void* p:m->p)if(p)cudaFree(p);if(m->blas)cublasDestroy(m->blas);if(m->stream)cudaStreamDestroy(m->stream);delete m;}extern "C" int cuda_bge_memory_info_impl(size_t* free_bytes,size_t* total_bytes){return free_bytes&&total_bytes&&ok(cudaMemGetInfo(free_bytes,total_bytes))?0:1;}
extern "C" int cuda_bge_diagnostics_impl(void* handle,uint64_t* values,size_t capacity){Model* m=(Model*)handle;if(!m||!values||capacity<25)return 1;uint64_t result[25]={m->forward_mallocs,m->forward_frees,m->kernel_launches,m->parameter_uploads,m->workspace_reallocations,m->h2d_bytes,m->d2h_bytes,m->synchronizations,m->graph_launches,m->internal_submissions,m->graph_captures,m->graph_invalidations,(uint64_t)m->last_batch,(uint64_t)m->last_seq,(uint64_t)m->graph_enabled,(uint64_t)m->last_graph_captured,(uint64_t)m->last_graph_reused,(uint64_t)(m->graph_exec!=nullptr),m->parameter_bytes,m->workspace_bytes,(uint64_t)m->precision,m->conversion_ns,m->upload_ns,m->validation_ns,m->transpose_ns};for(int i=0;i<25;i++)values[i]=result[i];return 0;}
